<?php // OpenFreeMap / MapLibre location explorer; property records will be connected later. ?>
<style>
.property-map-card{background:#fff;border:1px solid #e3e8ef;border-radius:14px;padding:18px}.property-map-search{display:flex;gap:8px;margin-bottom:12px}.property-map-search input{flex:1;min-width:0;min-height:42px;border:1px solid #d9e1eb;border-radius:8px;padding:10px;font:inherit;font-size:12px}.property-map-search button{border:0;border-radius:8px;padding:10px 16px;background:#2463a6;color:white;font:inherit;font-size:12px;cursor:pointer}#propertyExplorerMap{height:490px;border-radius:10px;overflow:hidden;background:#eef2f7}.map-help{font-size:12px;color:#6c7a8c;line-height:1.9;margin-top:12px}@media(max-width:560px){#propertyExplorerMap{height:350px}.property-map-search{flex-direction:column}}
</style>
<section class="property-map-card"><div class="property-map-search"><input id="mapPlaceSearch" type="search" placeholder="جستجوی آدرس یا نام مکان"><button type="button" id="mapPlaceSearchBtn">جستجو</button></div><div id="propertyExplorerMap"></div><p id="mapExplorerMessage" class="map-help">نقشه رایگان OpenFreeMap با نام خیابان‌ها و مکان‌ها. برای جستجوی آدرس از سرویس عمومی Nominatim استفاده می‌شود و محدودیت استفاده دارد.</p><p class="map-help">فعلاً نقشه برای مشاهده و انتخاب مکان فعال است؛ اتصال نقاط ثبت‌شده املاک به دیتابیس در مرحله بعد انجام می‌شود.</p></section>
<link rel="stylesheet" href="https://unpkg.com/maplibre-gl@5.6.2/dist/maplibre-gl.css"><script src="https://unpkg.com/maplibre-gl@5.6.2/dist/maplibre-gl.js"></script>
<script>(function(){const el=document.getElementById('propertyExplorerMap'),msg=document.getElementById('mapExplorerMessage'),input=document.getElementById('mapPlaceSearch');if(!window.maplibregl){el.textContent='نقشه بارگذاری نشد؛ اتصال اینترنت را بررسی کنید.';return;}const map=new maplibregl.Map({container:el,style:'https://tiles.openfreemap.org/styles/liberty',center:[69.2075,34.5553],zoom:11,attributionControl:true});map.addControl(new maplibregl.NavigationControl(),'top-left');let marker;function search(){const q=input.value.trim();if(!q)return;msg.textContent='در حال جستجوی مکان...';fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&accept-language=fa&q='+encodeURIComponent(q)).then(r=>{if(!r.ok)throw new Error();return r.json();}).then(rows=>{if(!rows.length){msg.textContent='مکان پیدا نشد؛ آدرس دیگری را امتحان کنید.';return;}const p=[Number(rows[0].lon),Number(rows[0].lat)];map.flyTo({center:p,zoom:15});if(marker)marker.setLngLat(p);else marker=new maplibregl.Marker({color:'#2463a6'}).setLngLat(p).addTo(map);msg.textContent=rows[0].display_name;}).catch(()=>{msg.textContent='جستجو در دسترس نیست؛ می‌توانید روی نقشه کلیک کنید.';});}document.getElementById('mapPlaceSearchBtn').addEventListener('click',search);input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();search();}});map.on('click',e=>{const p=[e.lngLat.lng,e.lngLat.lat];if(marker)marker.setLngLat(p);else marker=new maplibregl.Marker({color:'#2463a6'}).setLngLat(p).addTo(map);msg.textContent='مختصات انتخاب‌شده: '+p[1].toFixed(7)+', '+p[0].toFixed(7)+' — ذخیره دائمی پس از اتصال دیتابیس فعال می‌شود.';});})();</script>